def transform(grid):
    """Fill the blank tail of a partial full-width bar with color 1."""
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    for r, row in enumerate(grid):
        # Handle a bar attached to the left edge, followed only by background.
        if row[0] == bg:
            continue
        color = row[0]
        end = 0
        while end < len(row) and row[end] == color:
            end += 1
        if 0 < end < len(row) and all(v == bg for v in row[end:]):
            out[r][end:] = [1] * (len(row) - end)
    return out
